css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:80px}
*,*::before,*::after{box-sizing:inherit}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.12;letter-spacing:-.02em}
p{margin:0}a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
section{padding:88px 0}
.dark{background:var(--k);color:#fff}.dark2{background:var(--k2);color:#fff}.grey{background:var(--g)}
.dark p,.dark2 p{color:var(--dmute)}
.sh{max-width:640px;margin-bottom:44px}
.sh h2{font-size:clamp(28px,4vw,42px)}
.sh p{margin-top:14px;color:var(--mute);font-size:17px}
.dark .sh p,.dark2 .sh p{color:var(--dmute)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 22px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}
.b-l{background:var(--l);color:var(--k)}
.b-o{border-color:#ffffff40;color:#fff}.b-o:hover{background:#ffffff14}
.b-d{background:var(--k);color:#fff}
.b-w{border-color:#25D366;color:#25D366}.b-w:hover{background:#25D36618}
/* nav */
nav{position:sticky;top:0;z-index:20;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;list-style:none;margin:0;padding:0;font-size:14.5px;color:#d0d0d4}
nav ul a:hover{color:var(--l)}
nav .btn{padding:10px 18px;font-size:14px}
/* hero */
.hero{padding:72px 0 88px;overflow:hidden}
.hero .wrap{display:grid;grid-template-columns:1.05fr 1fr;gap:48px;align-items:center}
.hero h1{font-size:clamp(44px,7.4vw,92px);line-height:.98;letter-spacing:-.04em}
.hero h1 span{display:block}.hero h1 span:nth-child(2){color:var(--l)}
.hero .sub{margin:24px 0 32px;font-size:clamp(17px,2vw,20px);max-width:440px;color:#d6d6da}
.ctas{display:flex;flex-wrap:wrap;gap:12px}
.hero .note{margin-top:20px;font-size:14px}
.stage{position:relative;height:540px}
.stage svg{position:absolute;inset:0;width:100%;height:100%}
.m{position:absolute;background:var(--k2);border:1px solid var(--dline);border-radius:16px;box-shadow:0 20px 40px #0008}
.web{left:0;top:20px;width:330px;height:220px;overflow:hidden}
.bar{display:flex;gap:6px;padding:10px 12px;border-bottom:1px solid var(--dline)}.bar b{width:8px;height:8px;border-radius:50%;background:#333}
.web .bd{padding:16px}
.ln{height:8px;border-radius:4px;background:#2a2a2e;margin-bottom:9px}
.ln.h{height:16px;width:70%;background:#f0f0f0;margin-bottom:12px}.ln.s{width:55%}
.pill{display:inline-block;padding:7px 14px;border-radius:99px;background:var(--l);color:var(--k);font:600 11px Inter;margin-top:6px}
.app{right:30px;top:0;width:170px;height:330px;border-radius:28px;padding:14px;border-width:2px}
.app .nt{width:50px;height:5px;border-radius:3px;background:#333;margin:0 auto 14px}
.app .row{display:flex;align-items:center;gap:8px;padding:9px;border-radius:10px;background:#1b1b1f;margin-bottom:8px;font-size:11px;color:#ddd}
.app .row i{width:22px;height:22px;border-radius:7px;background:#2c2c31;flex:none}.app .row.on i{background:var(--l)}
.ai{left:60px;top:290px;width:260px;padding:16px;border-color:#C7FF3F55}
.ai h4{font-size:13px;margin-bottom:12px;color:#fff}
.fl{display:flex;align-items:center;gap:8px;font-size:11.5px;color:#cfcfd4}
.fl span{padding:6px 9px;border-radius:8px;background:#1d1d21;border:1px solid var(--dline)}.fl span.a{border-color:var(--l);color:var(--l)}.fl em{color:#555;font-style:normal}
.an{right:0;top:350px;width:250px;padding:16px}
.an small{color:var(--dmute);font-size:11.5px}
.bars{display:flex;align-items:flex-end;gap:7px;height:80px;margin-top:10px}
.bars i{flex:1;background:#2a2a2e;border-radius:4px 4px 0 0}.bars i:last-child{background:var(--l)}
.an .sk{font-size:11px;color:var(--dmute);margin-top:8px}
/* trust */
.trust{padding:36px 0;border-bottom:1px solid var(--line)}
.trust .wrap{display:flex;align-items:center;gap:28px;flex-wrap:wrap}
.trust p{font-size:14px;color:var(--mute);flex:none}
.logos{display:grid;grid-template-columns:repeat(5,1fr);gap:14px;flex:1;min-width:280px}
.logos div{height:46px;border:1.5px dashed #c9cac6;border-radius:10px;display:grid;place-items:center;font-size:12px;color:#9a9b97}
/* value */
.vals{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.val{background:#fff;border:1px solid var(--line);border-radius:20px;padding:30px}
.val .ic{width:46px;height:46px;border-radius:12px;background:var(--k);display:grid;place-items:center;margin-bottom:22px}
.val .ic svg{width:22px;height:22px;stroke:var(--l);fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.val h3{font-size:21px;margin-bottom:10px}.val p{color:var(--mute)}
/* bento */
.bento{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}
.bc{border-radius:22px;padding:30px;background:#fff;border:1px solid var(--line);position:relative;overflow:hidden}
.bc h3{font-size:22px;margin-bottom:10px}.bc p{color:var(--mute);max-width:420px}
.bc ul{margin:16px 0 0;padding:0;list-style:none;display:flex;flex-wrap:wrap;gap:8px}
.bc li{font-size:13px;padding:6px 12px;border-radius:99px;background:var(--g)}
.web-c{grid-column:span 3}.app-c{grid-column:span 3}.dm-c{grid-column:span 2}
.ai-c{grid-column:span 4;background:var(--k);border-color:var(--k);color:#fff;min-height:300px}
.ai-c p{color:var(--dmute)}.ai-c li{background:#1c1c20;color:#d8d8dc}
.ai-c .tag{display:inline-block;font:600 12px Inter;color:var(--k);background:var(--l);padding:5px 12px;border-radius:99px;margin-bottom:16px}
.nodes{display:flex;align-items:center;gap:10px;margin-top:26px;flex-wrap:wrap}
.nodes b{font:500 13px Inter;padding:10px 14px;border-radius:12px;border:1px solid var(--dline);background:#16161a;color:#fff}
.nodes b.a{border-color:var(--l);box-shadow:0 0 0 4px #C7FF3F18}
.nodes s{width:22px;height:2px;background:var(--l);text-decoration:none}
/* journey */
.jr{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;gap:18px;align-items:stretch}
.jc{border:1px solid var(--dline);border-radius:20px;padding:30px;background:var(--k2)}
.jc h3{font-size:26px;color:var(--l);margin-bottom:12px}
.jc ul{list-style:none;margin:16px 0 0;padding:0;color:#d4d4d8;font-size:15px}.jc li{padding:7px 0;border-top:1px solid var(--dline)}
.arr{align-self:center;color:var(--l);font:600 28px Sora}
/* work */
.work{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.wk{background:#fff;border:1px solid var(--line);border-radius:20px;overflow:hidden;display:flex;flex-direction:column}
.thumb{height:210px;background:var(--k);position:relative;padding:20px;display:flex;flex-direction:column;justify-content:flex-end;color:#fff}
.thumb .t1{font:700 26px Sora;letter-spacing:-.03em}.thumb .t2{font-size:13px;color:var(--dmute)}
.thumb .cp{position:absolute;top:16px;left:16px;font-size:11.5px;padding:4px 10px;border-radius:99px;background:var(--l);color:var(--k);font-weight:600}
.thumb .ph{position:absolute;top:16px;right:20px;width:70px;height:130px;border:2px solid #333;border-radius:14px;background:#17171a}
.thumb .ph::after{content:"";position:absolute;left:8px;right:8px;top:30px;height:34px;border-radius:6px;background:#2a2a2e}
.wk .bd{padding:24px;flex:1}.wk h3{font-size:19px;margin-bottom:8px}.wk p{color:var(--mute);font-size:15px}
.wk .tg{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.wk .tg span{font-size:12.5px;background:var(--g);padding:4px 10px;border-radius:99px}
.fine{margin-top:22px;font-size:14px;color:var(--mute)}
/* workflow */
.wf{display:grid;grid-template-columns:repeat(5,1fr);gap:0;position:relative}
.st{padding:0 12px;text-align:left;position:relative}
.st .dot{width:42px;height:42px;border-radius:50%;background:var(--k2);border:2px solid var(--dline);display:grid;place-items:center;margin-bottom:16px;position:relative;z-index:1}
.st .dot::after{content:"";width:12px;height:12px;border-radius:50%;background:var(--l)}
.st::before{content:"";position:absolute;left:54px;right:-12px;top:20px;height:2px;background:linear-gradient(90deg,var(--l),#2a2a2e)}
.st:last-child::before{display:none}
.st h4{font-size:16px;margin-bottom:6px;color:#fff}.st p{font-size:14px}
.wfx{margin-top:44px;display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.wfx div{border:1px solid var(--dline);border-radius:16px;padding:20px;font-size:14.5px;color:#d4d4d8}
.wfx b{display:block;font:600 16px Sora;color:#fff;margin-bottom:6px}
/* industries */
.ind{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.id{background:#fff;border:1px solid var(--line);border-radius:18px;padding:24px;transition:border-color .2s}
.id:hover{border-color:var(--k)}
.id h3{font-size:18px;margin-bottom:8px}.id p{font-size:14.5px;color:var(--mute)}
/* different */
.df{display:grid;grid-template-columns:repeat(2,1fr);gap:0 56px}
.df div{padding:26px 0;border-top:1px solid var(--dline)}
.df h3{font-size:20px;margin-bottom:8px}.df p{max-width:480px}
/* process */
.ps{display:grid;grid-template-columns:repeat(5,1fr);gap:16px;counter-reset:s}
.pc{background:#fff;border:1px solid var(--line);border-radius:18px;padding:24px;counter-increment:s}
.pc::before{content:counter(s);display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:var(--k);color:var(--l);font:600 14px Sora;margin-bottom:18px}
.pc h3{font-size:18px;margin-bottom:8px}.pc p{font-size:14.5px;color:var(--mute)}
/* team */
.tm{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.tc{text-align:left}.tc .av{aspect-ratio:1;border-radius:20px;background:var(--g);border:1.5px dashed #c9cac6;display:grid;place-items:center;font-size:13px;color:#9a9b97;margin-bottom:14px}
.tc h4{font-size:16px}.tc p{font-size:14px;color:var(--mute)}
/* stack */
.sk2{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.sk2 h4{font-size:15px;margin-bottom:12px;color:var(--l)}
.sk2 span{display:inline-block;margin:0 6px 8px 0;padding:6px 12px;border:1px solid var(--dline);border-radius:99px;font-size:13.5px;color:#d8d8dc}
/* faq */
.faq{max-width:780px}
details{border-top:1px solid var(--line);padding:20px 0}details:last-child{border-bottom:1px solid var(--line)}
summary{cursor:pointer;font:600 18px Sora;list-style:none;display:flex;justify-content:space-between;gap:16px}
summary::-webkit-details-marker{display:none}summary::after{content:"+";font-size:24px;line-height:1;transition:transform .2s}
details[open] summary::after{transform:rotate(45deg)}
details p{margin-top:12px;color:var(--mute);max-width:640px}
/* cta */
.cta{background:var(--l);color:var(--k);padding:96px 0}
.cta h2{font-size:clamp(34px,6vw,68px);letter-spacing:-.035em;max-width:760px}
.cta p{margin:18px 0 32px;font-size:18px;max-width:520px;color:#2a3300}
.cta .btn.b-o{border-color:var(--k);color:var(--k)}.cta .btn.b-o:hover{background:#0000000f}
/* footer */
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.ft{display:grid;grid-template-columns:1.6fr repeat(3,1fr);gap:40px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}
footer h4{font-size:14px;margin-bottom:14px}
footer ul{list-style:none;margin:0;padding:0}footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.big{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* responsive */
@media(max-width:1020px){
.hero .wrap{grid-template-columns:1fr}.stage{height:500px;max-width:560px}
.bento .web-c,.bento .app-c,.bento .dm-c,.bento .ai-c{grid-column:span 6}
.vals,.work{grid-template-columns:1fr}.ind,.tm,.sk2{grid-template-columns:repeat(2,1fr)}
.ps{grid-template-columns:repeat(2,1fr)}.wf{grid-template-columns:1fr;gap:26px}.st::before{display:none}.st{padding:0}
.jr{grid-template-columns:1fr}.arr{transform:rotate(90deg);justify-self:center}.wfx{grid-template-columns:1fr}
.df{grid-template-columns:1fr}.ft{grid-template-columns:1fr 1fr}}
@media(max-width:860px){nav ul{display:none}}
@media(max-width:600px){
section{padding:64px 0}.logos{grid-template-columns:repeat(2,1fr)}
.stage{height:auto;display:grid;grid-template-columns:1fr 1fr;gap:12px}.stage svg{display:none}
.m{position:static;width:auto!important;height:auto!important;box-shadow:none}.app{border-radius:20px;grid-row:span 2}.web{grid-column:span 2}
.ps,.ind,.tm,.sk2{grid-template-columns:1fr}.ctas .btn{width:100%;justify-content:center}.fl{flex-wrap:wrap}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
